@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted</h4>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for <strong>@_selectedCourseTitle</strong> has been received. You will be notified of your enrollment status via your university email.</p>
    </div>
    <a href="/courses">Back to Course Catalog</a>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <form method="post" @formname="enrollment" class="col-md-6">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" id="studentName" name="@nameof(_model.StudentName)" value="@_model.StudentName" class="form-control" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="@nameof(_model.StudentId)" value="@_model.StudentId" class="form-control" required placeholder="e.g., S12345678" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="@nameof(_model.CourseId)" class="form-select" required>
                <option value="">-- Select a Course --</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id" selected="@(course.Id == _model.CourseId)">@course.DepartmentCode @course.CourseNumber - @course.Title</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
        <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> _courses = new();
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (CourseId.HasValue && _model.CourseId == 0)
            _model.CourseId = CourseId.Value;

        // Check if this is a POST (form was submitted)
        if (!string.IsNullOrEmpty(_model.StudentName) && !string.IsNullOrEmpty(_model.StudentId) && _model.CourseId > 0)
        {
            var course = Catalog.GetCourse(_model.CourseId);
            _selectedCourseTitle = course is not null ? $"{course.DepartmentCode} {course.CourseNumber} - {course.Title}" : "Unknown Course";
            _submitted = true;
        }
    }
}

